/// Data model representing a single recipe generated by the AI.
/// This is the core data structure used throughout the application.
class Recipe {
  final String id;
  final String name;
  final String description;
  final String cookingTime;
  final String difficulty;
  final List<String> availableIngredients;
  final List<String> missingIngredients;
  final List<String> steps;
  final String imageUrl;
  final bool isFavourite;

  const Recipe({
    required this.id,
    required this.name,
    required this.description,
    required this.cookingTime,
    required this.difficulty,
    required this.availableIngredients,
    this.missingIngredients = const [],
    required this.steps,
    this.imageUrl = '',
    this.isFavourite = false,
  });

  /// Creates a Recipe from the JSON object returned by the Groq AI.
  /// Handles missing or malformed fields gracefully.
  factory Recipe.fromJson(Map<String, dynamic> json) {
    return Recipe(
      id: json['id'] as String? ?? DateTime.now().millisecondsSinceEpoch.toString(),
      name: json['name'] as String? ?? 'Unknown Recipe',
      description: json['description'] as String? ?? '',
      cookingTime: json['cooking_time'] as String? ?? 'Unknown',
      difficulty: json['difficulty'] as String? ?? 'Medium',
      availableIngredients: _parseStringList(json['available_ingredients']),
      missingIngredients: _parseStringList(json['missing_ingredients']),
      steps: _parseStringList(json['steps']),
      imageUrl: json['image_url'] as String? ?? '',
      isFavourite: json['is_favourite'] as bool? ?? false,
    );
  }

  /// Serialises a Recipe to JSON for local storage in SharedPreferences.
  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'name': name,
      'description': description,
      'cooking_time': cookingTime,
      'difficulty': difficulty,
      'available_ingredients': availableIngredients,
      'missing_ingredients': missingIngredients,
      'steps': steps,
      'image_url': imageUrl,
      'is_favourite': isFavourite,
    };
  }

  /// Returns a copy of this Recipe with modified fields.
  Recipe copyWith({
    String? id,
    String? name,
    String? description,
    String? cookingTime,
    String? difficulty,
    List<String>? availableIngredients,
    List<String>? missingIngredients,
    List<String>? steps,
    String? imageUrl,
    bool? isFavourite,
  }) {
    return Recipe(
      id: id ?? this.id,
      name: name ?? this.name,
      description: description ?? this.description,
      cookingTime: cookingTime ?? this.cookingTime,
      difficulty: difficulty ?? this.difficulty,
      availableIngredients: availableIngredients ?? this.availableIngredients,
      missingIngredients: missingIngredients ?? this.missingIngredients,
      steps: steps ?? this.steps,
      imageUrl: imageUrl ?? this.imageUrl,
      isFavourite: isFavourite ?? this.isFavourite,
    );
  }

  static List<String> _parseStringList(dynamic value) {
    if (value == null) return [];
    if (value is List) {
      return value.map((e) => e.toString()).toList();
    }
    return [];
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) || (other is Recipe && other.id == id);

  @override
  int get hashCode => id.hashCode;
}

/// Represents the user's meal preferences sent to the AI.
class MealPreferences {
  final List<String> ingredients;
  final String mealType;       // Breakfast, Lunch, Dinner, Snack
  final String dietPreference; // Vegetarian, Non-Vegetarian, Any
  final String cookingTime;    // Under 15 min, Under 30 min, etc.

  const MealPreferences({
    required this.ingredients,
    required this.mealType,
    required this.dietPreference,
    required this.cookingTime,
  });
}
